import{_ as o,o as r,c as t,ae as a}from"./chunks/framework.Dh1jimFm.js";const u=JSON.parse('{"title":"Import/Export Errors","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/import-export-errors.md","filePath":"troubleshooting/import-export-errors.md"}'),i={name:"troubleshooting/import-export-errors.md"};function l(n,e,s,p,d,g){return r(),t("div",null,e[0]||(e[0]=[a('<h1 id="import-export-errors" tabindex="-1">Import/Export Errors <a class="header-anchor" href="#import-export-errors" aria-label="Permalink to &quot;Import/Export Errors&quot;">​</a></h1><p>This page covers common problems when importing or exporting files.</p><h2 id="cannot-read-file-import-fails" tabindex="-1">“Cannot read file” / import fails <a class="header-anchor" href="#cannot-read-file-import-fails" aria-label="Permalink to &quot;“Cannot read file” / import fails&quot;">​</a></h2><p><strong>Common causes:</strong></p><ul><li>The file is open in Word (or another app)</li><li>The file is read-only or in a protected location</li><li>The file format doesn’t match the workflow</li></ul><p><strong>Fix:</strong></p><ol><li>Close the file everywhere (Word, CAT tool editors, preview panes)</li><li>Copy it to a simple path (for example <code>C:\\Temp\\</code>) and try again</li><li>Re-export from the CAT tool using the recommended bilingual/package format</li></ol><h2 id="memoq-bilingual-shows-no-segments" tabindex="-1">memoQ bilingual shows no segments <a class="header-anchor" href="#memoq-bilingual-shows-no-segments" aria-label="Permalink to &quot;memoQ bilingual shows no segments&quot;">​</a></h2><p><strong>Cause:</strong> Export format doesn’t contain the expected bilingual table.</p><p><strong>Fix:</strong></p><ul><li>Re-export from memoQ as <strong>Bilingual DOCX</strong> in a <strong>two-column table</strong> format.</li><li>Open the DOCX in Word and confirm it really contains a Source/Target table.</li></ul><h2 id="trados-sdlppx-fails-to-extract" tabindex="-1">Trados SDLPPX fails to extract <a class="header-anchor" href="#trados-sdlppx-fails-to-extract" aria-label="Permalink to &quot;Trados SDLPPX fails to extract&quot;">​</a></h2><p><strong>Common causes:</strong></p><ul><li>Corrupt/partial package</li><li>Unsupported package structure</li></ul><p><strong>Fix:</strong></p><ul><li>Ask for a fresh export from Trados Studio.</li><li>Ensure the package includes all required files.</li></ul><h2 id="garbled-characters-encoding-issues" tabindex="-1">Garbled characters / encoding issues <a class="header-anchor" href="#garbled-characters-encoding-issues" aria-label="Permalink to &quot;Garbled characters / encoding issues&quot;">​</a></h2><p><strong>Cause:</strong> Text encoding problems coming from the source file or export.</p><p><strong>Fix:</strong></p><ul><li>Try <strong>Tools → Encoding Repair</strong>.</li><li>Re-export from the source tool with a modern Unicode/UTF-8 friendly path when possible.</li></ul><h2 id="segments-don-t-match-on-reimport" tabindex="-1">Segments don’t match on reimport <a class="header-anchor" href="#segments-don-t-match-on-reimport" aria-label="Permalink to &quot;Segments don’t match on reimport&quot;">​</a></h2><p><strong>Cause:</strong> Segment structure changed.</p><p><strong>Fix:</strong></p><ul><li>Don’t merge or split segments in Supervertaler</li><li>Export using the matching CAT format</li><li>Avoid deleting placeholder/tag-only segments</li></ul><h2 id="source-file-not-found-during-export" tabindex="-1">“Source file not found” during export <a class="header-anchor" href="#source-file-not-found-during-export" aria-label="Permalink to &quot;“Source file not found” during export&quot;">​</a></h2><p><strong>Cause:</strong> The original source file/folder was moved after import.</p><p><strong>Fix:</strong></p><ul><li>Use <strong>File → Relocate Source Folder</strong> and point it to the new location.</li><li>If the original source is gone, re-import the project from the correct source.</li></ul><h2 id="exported-file-has-no-translations" tabindex="-1">Exported file has no translations <a class="header-anchor" href="#exported-file-has-no-translations" aria-label="Permalink to &quot;Exported file has no translations&quot;">​</a></h2><p><strong>Cause:</strong> Targets are empty or the wrong export format was chosen.</p><p><strong>Fix:</strong></p><ul><li>Verify the Target column contains translations.</li><li>Export the matching format for the workflow you imported.</li></ul><h2 id="formatting-lost-on-reimport" tabindex="-1">Formatting lost on reimport <a class="header-anchor" href="#formatting-lost-on-reimport" aria-label="Permalink to &quot;Formatting lost on reimport&quot;">​</a></h2><p><strong>Cause:</strong> Tags not preserved.</p><p><strong>Fix:</strong></p><ul><li>Verify tags are balanced (for example <code>&lt;b&gt;text&lt;/b&gt;</code>)</li><li>Don’t delete CAT placeholder tags</li><li>Re-export using the correct CAT workflow</li></ul><h2 id="bilingual-table-reimport-fails" tabindex="-1">Bilingual table reimport fails <a class="header-anchor" href="#bilingual-table-reimport-fails" aria-label="Permalink to &quot;Bilingual table reimport fails&quot;">​</a></h2><p><strong>Cause:</strong> Bilingual tables are great for review, but not always suitable for CAT tool reimport.</p><p><strong>Fix:</strong></p><ul><li>Prefer the dedicated CAT exchange formats (memoQ/Trados/Phrase/CafeTran).</li><li>If you must use a bilingual table, don’t edit the table structure in Word.</li></ul>',40)]))}const h=o(i,[["render",l]]);export{u as __pageData,h as default};
